pub fn code(fmt: u8) -> String {
	match fmt {
		0 => "local q=C[b+1] local st=c local by=(\"\")[\"byte\"] local ch=(\"\")[\"char\"] local up=unpack or table.unpack local tc=table.concat local n=#q local out=\"\" local _pv=0 if n>0 then if n<=64 then local _ob={} for i=1,n do st=(st*257+d+i+_pv)%65521 local _x=(st+(st%256)*((st-(st%256))/256))%65521 _x=(_x*257+((_x-(_x%256))/256))%65521 local _v=(by(q,i)-(((_x%256)+(((_x-(_x%256))/256)%256))%256))%256 _ob[i]=_v _pv=_v end out=ch(up(_ob,1,n)) else local _ot,_on,_ob,_ok={},0,{},0 for i=1,n do st=(st*257+d+i+_pv)%65521 local _x=(st+(st%256)*((st-(st%256))/256))%65521 _x=(_x*257+((_x-(_x%256))/256))%65521 local _v=(by(q,i)-(((_x%256)+(((_x-(_x%256))/256)%256))%256))%256 _ok=_ok+1 _ob[_ok]=_v _pv=_v if _ok==64 then _on=_on+1 _ot[_on]=ch(up(_ob,1,64)) _ok=0 end end if _ok>0 then _on=_on+1 _ot[_on]=ch(up(_ob,1,_ok)) end out=tc(_ot) end end V[a+1]=out".to_string(),
		_ => "local st=c local q=C[b+1] local ch=(\"\")[\"char\"] local by=(\"\")[\"byte\"] local up=unpack or table.unpack local tc=table.concat local n=#q local out=\"\" local _pv=0 if n>0 then if n<=64 then local _ob={} for i=1,n do st=(257*st+d+i+_pv)%65521 local _x=(st+(st%256)*((st-(st%256))/256))%65521 _x=(_x*257+((_x-(_x%256))/256))%65521 local _v=(by(q,i)-(((_x%256)+(((_x-(_x%256))/256)%256))%256))%256 _ob[i]=_v _pv=_v end out=ch(up(_ob,1,n)) else local _ot,_on,_ob,_ok={},0,{},0 for i=1,n do st=(257*st+d+i+_pv)%65521 local _x=(st+(st%256)*((st-(st%256))/256))%65521 _x=(_x*257+((_x-(_x%256))/256))%65521 local _v=(by(q,i)-(((_x%256)+(((_x-(_x%256))/256)%256))%256))%256 _ok=_ok+1 _ob[_ok]=_v _pv=_v if _ok==64 then _on=_on+1 _ot[_on]=ch(up(_ob,1,64)) _ok=0 end end if _ok>0 then _on=_on+1 _ot[_on]=ch(up(_ob,1,_ok)) end out=tc(_ot) end end V[a+1]=out".to_string(),
	}
}
